-- Gated, customer-facing manual UPI preview. Apply only to an authorized staging database.
begin;
alter table kdial_private.listings add column package_inclusions text check(package_inclusions is null or length(package_inclusions) between 10 and 2000);
alter table kdial_private.listings add column cancellation_refund_terms text check(cancellation_refund_terms is null or length(cancellation_refund_terms) between 10 and 1500);

create table kdial_private.payment_offers (
 listing_id uuid primary key references kdial_private.listings(id) on delete cascade,
 offer_token uuid not null unique,
 created_at timestamptz not null default now()
);
create table kdial_private.payment_assets (
 asset_key text primary key check(asset_key='temporary-upi-qr'),
 content_type text not null check(content_type='image/jpeg'),
 content bytea not null,
 sha256 text not null
);
insert into kdial_private.payment_assets(asset_key,content_type,content,sha256) values
 ('temporary-upi-qr','image/jpeg',decode('','base64'),'78d975375306c582db1ced4dbdf715c3ae0effeb742882bb1ec5004673f4cad4');
alter table kdial_private.payment_offers enable row level security;
alter table kdial_private.payment_assets enable row level security;
revoke all on kdial_private.payment_offers,kdial_private.payment_assets from public,anon,authenticated;

create function public.kdial_admin_configure_payment_offer(listing_id uuid, package_inclusions text, cancellation_refund_terms text) returns uuid language plpgsql security definer set search_path = '' as $$
declare b kdial_private.listings; token uuid;
begin
 perform kdial_private.require_role(array['owner']);
 if coalesce(length(trim(package_inclusions)),0) not between 10 and 2000 then raise exception 'Exact package inclusions are required'; end if;
 if coalesce(length(trim(cancellation_refund_terms)),0) not between 10 and 1500 then raise exception 'Final cancellation and refund wording is required'; end if;
 select * into b from kdial_private.listings where id=kdial_admin_configure_payment_offer.listing_id for update;
 if not found then raise exception 'Listing not found'; end if;
 if b.content_status<>'approved' or b.content_verified_by is null or b.content_verified_at is null or coalesce(length(b.consent_reference),0)=0 then raise exception 'Approve the business details and publication consent before preparing a customer offer'; end if;
 if not b.terms_confirmed or b.currency<>'INR' or b.agreed_amount_minor<>50100 then raise exception 'The owner must record the agreed ₹501 first-year amount before preparing the customer offer'; end if;
 if b.publication_status<>'unpublished' then raise exception 'Payment offers are only for unpublished listings'; end if;
 update kdial_private.listings set package_inclusions=trim(kdial_admin_configure_payment_offer.package_inclusions), cancellation_refund_terms=trim(kdial_admin_configure_payment_offer.cancellation_refund_terms) where id=kdial_admin_configure_payment_offer.listing_id;
 token=gen_random_uuid();
 insert into kdial_private.payment_offers(listing_id,offer_token) values(kdial_admin_configure_payment_offer.listing_id,token) on conflict on constraint payment_offers_pkey do update set offer_token=excluded.offer_token,created_at=now();
 perform kdial_private.audit(kdial_admin_configure_payment_offer.listing_id,'customer_payment_offer_prepared',jsonb_build_object('amount_minor',b.agreed_amount_minor,'destination','temporary_personal_upi'));
 return token;
end $$;

create function public.kdial_public_payment_offer(offer_token uuid) returns jsonb language sql stable security definer set search_path = '' as $$
 select jsonb_build_object(
  'business_name',b.name,'amount_minor',b.agreed_amount_minor,'currency','INR',
  'package_inclusions',b.package_inclusions,'cancellation_refund_terms',b.cancellation_refund_terms,
  'first_year_label','₹501 for the first year; the term begins on publication.',
  'renewal_label','₹701 manual renewal after the first year; no automatic charge.',
  'payee','Felix Williams','upi_id','7356137106@superyes',
  'qr_base64',replace(replace(encode(asset.content,'base64'),chr(10),''),chr(13),''),
  'payment_status','report_only')
 from kdial_private.payment_offers o
 join kdial_private.listings b on b.id=o.listing_id
 join kdial_private.payment_assets asset on asset.asset_key='temporary-upi-qr'
 where o.offer_token=kdial_public_payment_offer.offer_token
  and b.content_status='approved' and b.content_verified_by is not null and b.content_verified_at is not null
  and coalesce(length(b.consent_reference),0)>0 and b.terms_confirmed and b.currency='INR'
  and b.agreed_amount_minor=50100 and length(coalesce(b.package_inclusions,''))>=10
  and length(coalesce(b.cancellation_refund_terms,''))>=10
  and b.publication_status='unpublished' and b.payment_status not in ('bank_verified','rejected');
$$;

create function public.kdial_service_report_public_payment(offer_token uuid, event_key text, evidence_reference text) returns jsonb language plpgsql security definer set search_path = '' as $$
declare b kdial_private.listings; existing kdial_private.payment_reports; report_id uuid;
begin
 if coalesce(length(event_key),0)<>64 or coalesce(length(trim(evidence_reference)),0) not between 3 and 120 or evidence_reference !~ '^[A-Za-z0-9._/-]+$' then raise exception 'Invalid payment report'; end if;
 select l.* into b from kdial_private.payment_offers o join kdial_private.listings l on l.id=o.listing_id
 where o.offer_token=kdial_service_report_public_payment.offer_token for update of l;
 if not found or b.content_status<>'approved' or b.content_verified_by is null or b.content_verified_at is null
  or coalesce(length(b.consent_reference),0)=0 or not b.terms_confirmed or b.currency<>'INR' or b.agreed_amount_minor<>50100
  or length(coalesce(b.package_inclusions,''))<10 or length(coalesce(b.cancellation_refund_terms,''))<10
  or b.publication_status<>'unpublished' or b.payment_status in ('bank_verified','rejected') then raise exception 'Payment offer is unavailable'; end if;
 select * into existing from kdial_private.payment_reports r where r.event_key=kdial_service_report_public_payment.event_key;
 if found then
  if existing.listing_id<>b.id or existing.evidence_reference<>evidence_reference or existing.source<>'manual' then raise exception 'Conflicting payment report'; end if;
  return jsonb_build_object('status','reported','report_id',existing.id);
 end if;
 if (select count(*) from kdial_private.payment_reports r where r.listing_id=b.id and r.created_at>now()-interval '1 hour')>=20 then raise exception 'Too many reports. Contact KDial for help.'; end if;
 insert into kdial_private.payment_reports(listing_id,event_key,source,amount_minor,evidence_reference,reported_by)
 values(b.id,event_key,'manual',b.agreed_amount_minor,evidence_reference,null) returning id into report_id;
 update kdial_private.listings set payment_status=case when payment_status='bank_verified' then payment_status else 'reported' end where id=b.id;
 perform kdial_private.audit(b.id,'customer_payment_reported',jsonb_build_object('source','manual','report_id',report_id));
 return jsonb_build_object('status','reported','report_id',report_id);
end $$;

revoke all on function public.kdial_admin_configure_payment_offer(uuid,text,text) from public,anon,authenticated;
grant execute on function public.kdial_admin_configure_payment_offer(uuid,text,text) to authenticated;
revoke all on function public.kdial_public_payment_offer(uuid) from public;
grant execute on function public.kdial_public_payment_offer(uuid) to anon,authenticated;
revoke all on function public.kdial_service_report_public_payment(uuid,text,text) from public,anon,authenticated;
grant execute on function public.kdial_service_report_public_payment(uuid,text,text) to service_role;
commit;
